Here's a basic login implementation using Node.js, Express, bcrypt for password hashing, and JWT for sessions. Adjust it if your project uses a different stack.

**1. Install dependencies**

```bash
npm install express bcrypt jsonwebtoken
```

**2. Server code (`server.js`)**

```javascript
const express = require('express');
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');

const app = express();
app.use(express.json());

const JWT_SECRET = process.env.JWT_SECRET || 'change-me-in-production';

// Example in-memory user store. Replace with a real database.
const users = [];

// Register a user
app.post('/register', async (req, res) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password are required' });
  }

  if (users.find(u => u.email === email)) {
    return res.status(409).json({ error: 'User already exists' });
  }

  const passwordHash = await bcrypt.hash(password, 12);
  users.push({ id: users.length + 1, email, passwordHash });

  res.status(201).json({ message: 'User registered' });
});

// Log in
app.post('/login', async (req, res) => {
  const { email, password } = req.body;

  const user = users.find(u => u.email === email);
  // Use the same error message whether the email or password is wrong
  // so attackers can't tell which accounts exist.
  if (!user) {
    return res.status(401).json({ error: 'Invalid email or password' });
  }

  const valid = await bcrypt.compare(password, user.passwordHash);
  if (!valid) {
    return res.status(401).json({ error: 'Invalid email or password' });
  }

  const token = jwt.sign(
    { sub: user.id, email: user.email },
    JWT_SECRET,
    { expiresIn: '1h' }
  );

  res.json({ token });
});

// Middleware to protect routes
function requireAuth(req, res, next) {
  const header = req.headers.authorization || '';
  const token = header.startsWith('Bearer ') ? header.slice(7) : null;

  if (!token) {
    return res.status(401).json({ error: 'Missing token' });
  }

  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch {
    res.status(401).json({ error: 'Invalid or expired token' });
  }
}

// Example protected route
app.get('/profile', requireAuth, (req, res) => {
  res.json({ id: req.user.sub, email: req.user.email });
});

app.listen(3000, () => console.log('Server running on port 3000'));
```

**3. Testing it**

```bash
curl -X POST http://localhost:3000/register \
  -H "Content-Type: application/json" \
  -d '{"email":"test@example.com","password":"secret123"}'

curl -X POST http://localhost:3000/login \
  -H "Content-Type: application/json" \
  -d '{"email":"test@example.com","password":"secret123"}'

curl http://localhost:3000/profile \
  -H "Authorization: Bearer <token-from-login>"
```

**Notes for production:**
- Store users in a database, not an array.
- Set `JWT_SECRET` as an environment variable, and use a long random value.
- Serve everything over HTTPS.
- Add rate limiting on `/login` to slow brute-force attempts.
- Consider short-lived access tokens with refresh tokens if you need longer sessions.

