const express = require('express');
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');
const cookieParser = require('cookie-parser');

const app = express();
app.use(express.json());
app.use(cookieParser());

const JWT_SECRET = process.env.JWT_SECRET; // Set this in your environment

// Placeholder user store. Replace with your database lookup.
const users = [
  {
    id: 1,
    email: 'user@example.com',
    // Pre-hashed password for "password123"
    passwordHash: bcrypt.hashSync('password123', 10),
  },
];

// Login route
app.post('/api/login', async (req, res) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password are required' });
  }

  const user = users.find((u) => u.email === email);

  // Use the same generic message for unknown email and wrong password
  // so attackers can't use the response to discover valid accounts.
  if (!user) {
    return res.status(401).json({ error: 'Invalid email or password' });
  }

  const passwordMatches = await bcrypt.compare(password, user.passwordHash);
  if (!passwordMatches) {
    return res.status(401).json({ error: 'Invalid email or password' });
  }

  const token = jwt.sign({ sub: user.id, email: user.email }, JWT_SECRET, {
    expiresIn: '1h',
  });

  // Store the token in an httpOnly cookie so JavaScript can't read it
  res.cookie('token', token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict',
    maxAge: 60 * 60 * 1000,
  });

  res.json({ message: 'Logged in successfully' });
});

// Middleware to protect routes
function requireAuth(req, res, next) {
  const token = req.cookies.token;
  if (!token) {
    return res.status(401).json({ error: 'Not authenticated' });
  }

  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
}

// Example protected route
app.get('/api/profile', requireAuth, (req, res) => {
  res.json({ userId: req.user.sub, email: req.user.email });
});

// Logout route
app.post('/api/logout', (req, res) => {
  res.clearCookie('token');
  res.json({ message: 'Logged out' });
});

app.listen(3000, () => console.log('Server running on port 3000'));
```

